def get_initial_stage(task_type, target_type):
    if 'pick_two' in task_type or 'pick_and_place' in task_type:
        return 'find_target'
    if 'clean' in task_type:
        return 'find_target'
    if 'cool' in task_type or 'heat' in task_type:
        return 'find_target'
    if 'put' in task_type:
        return 'find_target'
    return 'find_target'

def hook(ctx, nb):
    task_type = ctx.get('task', {}).get('task_type', '')
    target_type = ctx.get('task', {}).get('target_type', '')
    dest_type = ctx.get('task', {}).get('destination_type', '')
    nb['stage'] = get_initial_stage(task_type, target_type)
    nb['placed_count'] = 0
    nb['placed_items'] = []
    nb['last_hint'] = None
    nb['target_found'] = False
    nb['has_target'] = False
    nb['transform_done'] = False
    hint = 'Focus on one subgoal at a time: find target, take it, apply transform if needed, go to destination, put it there.'
    return {'skills': [{'text': hint}], 'tool_hint': 'Use inventory to check what you carry. Examine containers to find targets. For clean/cool/heat tasks, apply transform before putting.'}

def parse_action_type(action):
    if not action:
        return 'unknown'
    action = action.lower()
    if action.startswith('go to'):
        return 'go'
    if action.startswith('take'):
        return 'take'
    if action.startswith('put'):
        return 'put'
    if action.startswith('open'):
        return 'open'
    if action.startswith('close'):
        return 'close'
    if action.startswith('clean'):
        return 'clean'
    if action.startswith('cool'):
        return 'cool'
    if action.startswith('heat'):
        return 'heat'
    if action.startswith('examine'):
        return 'examine'
    if action.startswith('inventory'):
        return 'inventory'
    if action.startswith('look'):
        return 'look'
    return 'other'

def update_stage_from_action(ctx, nb, action_type):
    task_type = ctx.get('task', {}).get('task_type', '')
    target_type = ctx.get('task', {}).get('target_type', '')
    obs = ctx.get('observation', '')
    inv = ctx.get('world', {}).get('inventory', [])
    stage = nb.get('stage', 'find_target')
    has_target = len(inv) > 0
    nb['has_target'] = has_target
    if action_type == 'take':
        if 'pick_two' in task_type:
            nb['stage'] = 'transform' if 'clean' in task_type or 'cool' in task_type or 'heat' in task_type else 'go_destination'
        else:
            nb['stage'] = 'transform' if 'clean' in task_type or 'cool' in task_type or 'heat' in task_type else 'go_destination'
        nb['target_found'] = True
    elif action_type in ['clean', 'cool', 'heat']:
        nb['transform_done'] = True
        nb['stage'] = 'go_destination'
    elif action_type == 'put':
        if 'pick_two' in task_type:
            nb['placed_count'] = nb.get('placed_count', 0) + 1
            if nb['placed_count'] >= 2:
                nb['stage'] = 'done'
            else:
                nb['stage'] = 'find_target'
                nb['transform_done'] = False
        else:
            nb['stage'] = 'done'
    elif action_type == 'go':
        if stage == 'go_destination' and has_target:
            nb['stage'] = 'put_target'
    return nb

def hook(ctx, nb):
    action = ctx.get('action', {}).get('raw', '')
    action_type = parse_action_type(action)
    nb = update_stage_from_action(ctx, nb, action_type)
    inv = ctx.get('world', {}).get('inventory', [])
    nb['has_target'] = len(inv) > 0
    return None

def detect_loop(ctx, nb):
    rep_obs = ctx.get('state', {}).get('repeated_observation_count', 0)
    rep_act = ctx.get('state', {}).get('repeated_action_count', 0)
    return rep_obs > 3 or rep_act > 3

def get_stage_hint(stage, task_type, has_target, transform_done):
    if stage == 'find_target':
        return 'Search for the target object by examining containers. Use go to navigate, then examine or open receptacles.'
    elif stage == 'take_target':
        return 'Take the target object using take <object> from <receptacle>.'
    elif stage == 'transform':
        if 'clean' in task_type:
            return 'Clean the object at a sinkbasin using clean <object> with sinkbasin.'
        elif 'cool' in task_type:
            return 'Cool the object using a fridge or countertop with cool <object> with <receptacle>.'
        elif 'heat' in task_type:
            return 'Heat the object using a microwave or stoveburner with heat <object> with <receptacle>.'
        return 'Apply the required transformation before proceeding.'
    elif stage == 'go_destination':
        return 'Navigate to the destination receptacle using go to <destination>.'
    elif stage == 'put_target':
        return 'Put the object in the destination using put <object> in/on <receptacle>.'
    return None

def hook(ctx, nb):
    if detect_loop(ctx, nb):
        stage = nb.get('stage', 'find_target')
        task_type = ctx.get('task', {}).get('task_type', '')
        has_target = nb.get('has_target', False)
        transform_done = nb.get('transform_done', False)
        hint = get_stage_hint(stage, task_type, has_target, transform_done)
        if hint and hint != nb.get('last_hint'):
            nb['last_hint'] = hint
            return {'message': hint}
    return None

def find_admissible_action(ctx, prefix):
    admissible = ctx.get('admissible', [])
    prefix = prefix.lower()
    for a in admissible:
        if a.lower().startswith(prefix):
            return a
    return None

def hook(ctx, nb):
    action = ctx.get('action', {}).get('raw', '')
    if not action:
        return None
    stage = nb.get('stage', 'find_target')
    task_type = ctx.get('task', {}).get('task_type', '')
    target_type = ctx.get('task', {}).get('target_type', '')
    has_target = nb.get('has_target', False)
    transform_done = nb.get('transform_done', False)
    admissible = ctx.get('admissible', [])
    if stage == 'take_target' and not has_target:
        for a in admissible:
            if a.lower().startswith('take') and target_type and target_type in a.lower():
                return {'kind': 'force_action', 'action': a, 'message': 'Take the target object first.'}
    if stage == 'transform' and has_target and not transform_done:
        if 'clean' in task_type:
            for a in admissible:
                if a.lower().startswith('clean'):
                    return {'kind': 'force_action', 'action': a, 'message': 'Clean the object before putting it.'}
        elif 'cool' in task_type:
            for a in admissible:
                if a.lower().startswith('cool'):
                    return {'kind': 'force_action', 'action': a, 'message': 'Cool the object before putting it.'}
        elif 'heat' in task_type:
            for a in admissible:
                if a.lower().startswith('heat'):
                    return {'kind': 'force_action', 'action': a, 'message': 'Heat the object before putting it.'}
    if stage == 'put_target' and has_target:
        for a in admissible:
            if a.lower().startswith('put'):
                return {'kind': 'force_action', 'action': a, 'message': 'Put the object in the destination.'}
    return None
